package com.example.orchestration.controller;import com.example.orchestration.workflow.*;import io.swagger.v3.oas.annotations.Operation;import jakarta.validation.Valid;import io.temporal.client.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.Map;@RestController @RequestMapping("/api/workflows/orders")public class WorkflowController{private final WorkflowClient client;public WorkflowController(WorkflowClient c){client=c;}@PostMapping @Operation(summary="Start durable order lifecycle")public ResponseEntity<Map<String,String>>start(@Valid@RequestBody OrderWorkflowRequest r){String id="order-"+r.orderId();OrderLifecycleWorkflow w=client.newWorkflowStub(OrderLifecycleWorkflow.class,WorkflowOptions.newBuilder().setWorkflowId(id).setTaskQueue("order-lifecycle").build());WorkflowClient.start(w::run,r);return ResponseEntity.accepted().body(Map.of("workflowId",id,"status","STARTED"));}@GetMapping("/{orderId}")public Map<String,String>status(@PathVariable String orderId){OrderLifecycleWorkflow w=client.newWorkflowStub(OrderLifecycleWorkflow.class,"order-"+orderId);return Map.of("workflowId","order-"+orderId,"status",w.status());}}
